// step, all in one call. begin is the implicit "BEGIN ..." to run first when the connection is in autocommit
// (CPython's legacy isolation_level); text 1 also reads the first row, so a point query needs no fetch call.
// Returns the result code, the column count, names and declared types, the connection's changes and last
// insert rowid, the first row (text 1) and the column whose text is not UTF-8 (-1: none). The result code is
// -1 when the parameters need Python (a dict, other types, a count that is off).
#[allow(clippy::type_complexity)]
fn run_fast(o: &SqlOps, stmt: i64, db: i64, ps: &[V], begin: Option<&str>, text: i64)
    -> (i64, i64, Vec<V>, Vec<V>, i64, i64, Vec<V>, i64) {
    let none = || (-1, 0, vec![], vec![], 0, 0, vec![], -1);
    if let Some(begin) = begin {
        if (o.db_int)(db, 3) != 0 {
            let (rc, bst, _used) = (o.prepare)(db, begin.as_bytes());
            if rc != 0 {
                return (rc, 0, vec![], vec![], 0, 0, vec![], -1);
            }
            if bst != 0 {
                let rc = (o.step)(bst);
                (o.finalize)(bst);
                if rc != 100 && rc != 101 {
                    return (rc, 0, vec![], vec![], 0, 0, vec![], -1);
                }
            }
        }
    }
    if ps.len() as i64 != (o.nparams)(stmt) {
        return none();
    }
    for v in ps {
        let ok = matches!(v, V::None | V::Int(_) | V::Float(_) | V::Str(_))
            || matches!(v, V::Ext(x) if x.any().is::<BytesV>());
        if !ok {
            return none();
        }
    }
    (o.reset)(stmt);
    for (k, v) in ps.iter().enumerate() {
        if (o.bind)(stmt, k as i64 + 1, v) != 0 {
            return none();
        }
    }
    let rc = (o.step)(stmt);
    let nc = if rc == 100 || rc == 101 { (o.ncols)(stmt) } else { 0 };
    let mut names = Vec::with_capacity(nc as usize);
    let mut decls = Vec::with_capacity(nc as usize);
    for k in 0..nc {
        names.push(st(String::from_utf8_lossy(&(o.col_name)(stmt, k)).into_owned()));
        decls.push((o.col_decl)(stmt, k).map_or(V::None, st));
    }
    let mut row = vec![];
    let mut bad = -1;
    if text == 1 && rc == 100 {
        row = Vec::with_capacity(nc as usize);
        for k in 0..nc {
            match dbv_py((o.col)(stmt, k), 1) {
                Ok(v) => row.push(v),
                Err(b) => {
                    if bad < 0 {
                        bad = k;
                    }
                    row.push(bytesv(b));
                }
            }
        }
    }
    (rc, nc, names, decls, (o.db_int)(db, 0), (o.db_int)(db, 2), row, bad)
